public func SUIColor(_ r: Double, _ g: Double, _ b: Double, _ a: Double) -> UnsafeMutableRawPointer {
    let view = AnyView(Color(red: r, green: g, blue: b, opacity: a))
    return retainView(view)
}

@_cdecl("SUICircle")
public func SUICircle() -> UnsafeMutableRawPointer {
    let shape = Circle()
    return retainView(AnyView(shape), shape: AnyShape(shape))
}

@_cdecl("SUIRectangle")
public func SUIRectangle() -> UnsafeMutableRawPointer {
    let shape = Rectangle()
    return retainView(AnyView(shape), shape: AnyShape(shape))
}

@_cdecl("SUIRoundedRectangle")
public func SUIRoundedRectangle(_ cornerRadius: Double) -> UnsafeMutableRawPointer {
    let shape = RoundedRectangle(cornerRadius: cornerRadius)
    return retainView(AnyView(shape), shape: AnyShape(shape))
}

@_cdecl("SUICapsule")
public func SUICapsule() -> UnsafeMutableRawPointer {
    let shape = Capsule()
    return retainView(AnyView(shape), shape: AnyShape(shape))
}

@_cdecl("SUILink")
public func SUILink(_ titlePtr: UnsafePointer<CChar>, _ urlPtr: UnsafePointer<CChar>) -> UnsafeMutableRawPointer {
    let title = String(cString: titlePtr)
    let urlString = String(cString: urlPtr)
    let view: AnyView
    if let url = URL(string: urlString) {
        view = AnyView(Link(title, destination: url))
    } else {
        view = AnyView(Text(title))
    }
    return Unmanaged.passRetained(Box(view)).toOpaque()
}

@_cdecl("SUIGauge")
public func SUIGauge(_ value: Double, _ labelPtr: UnsafePointer<CChar>) -> UnsafeMutableRawPointer {
    let label = String(cString: labelPtr)
    let view = AnyView(Gauge(value: value) { Text(label) })
    return Unmanaged.passRetained(Box(view)).toOpaque()
}

@_cdecl("SUIWebPageCreate")
@MainActor
public func SUIWebPageCreate() -> UnsafeMutableRawPointer {
    let page = WebPage()
    return Unmanaged.passRetained(page).toOpaque()
}

@_cdecl("SUIWebPageLoadURL")
@MainActor
public func SUIWebPageLoadURL(_ pageRef: UnsafeMutableRawPointer, _ urlPtr: UnsafePointer<CChar>) {
    let page = Unmanaged<WebPage>.fromOpaque(pageRef).takeUnretainedValue()
    let urlString = String(cString: urlPtr)
    guard let url = URL(string: urlString) else {
        return
    }
    page.load(URLRequest(url: url))
}

@_cdecl("SUIWebPageReload")
@MainActor
public func SUIWebPageReload(_ pageRef: UnsafeMutableRawPointer) {
    let page = Unmanaged<WebPage>.fromOpaque(pageRef).takeUnretainedValue()
    page.reload()
}

@_cdecl("SUIWebViewPage")
@MainActor
public func SUIWebViewPage(_ pageRef: UnsafeMutableRawPointer) -> UnsafeMutableRawPointer {
    let page = Unmanaged<WebPage>.fromOpaque(pageRef).takeUnretainedValue()
    let view = AnyView(WebView(page))
    return Unmanaged.passRetained(Box(view)).toOpaque()
}

// MARK: - Binding views

@_cdecl("SUIToggle")
@MainActor
public func SUIToggle(_ labelPtr: UnsafePointer<CChar>, _ stateRef: UnsafeMutableRawPointer, _ callbackID: UInt) -> UnsafeMutableRawPointer {
    let label = String(cString: labelPtr)
    let state = Unmanaged<BridgedIntState>.fromOpaque(stateRef).takeUnretainedValue()
    let view = AnyView(BridgedToggle(label: label, state: state, callbackID: callbackID))
    return Unmanaged.passRetained(Box(view)).toOpaque()
}

@MainActor
struct BridgedToggle: View {
    let label: String
    var state: BridgedIntState
    let callbackID: UInt

    var body: some View {
        Toggle(label, isOn: Binding(
            get: { state.value != 0 },
            set: { newValue in
                state.value = newValue ? 1 : 0
                _SUIButtonCallback?(callbackID)
            }
        ))
    }
}

@_cdecl("SUITextField")
@MainActor
public func SUITextField(_ placeholderPtr: UnsafePointer<CChar>, _ stateRef: UnsafeMutableRawPointer, _ onSubmitID: UInt) -> UnsafeMutableRawPointer {
    let placeholder = String(cString: placeholderPtr)
    let state = Unmanaged<BridgedStringState>.fromOpaque(stateRef).takeUnretainedValue()
    let view = AnyView(BridgedTextField(placeholder: placeholder, state: state, onSubmitID: onSubmitID))
    return Unmanaged.passRetained(Box(view)).toOpaque()
}

@MainActor
struct BridgedTextField: View {
    let placeholder: String
    var state: BridgedStringState
    let onSubmitID: UInt

    var body: some View {
        TextField(placeholder, text: Binding(
            get: { state.value },
            set: { state.value = $0 }
        ))
        .onSubmit {
            _SUIButtonCallback?(onSubmitID)
        }
    }
}

