@_cdecl("SUITextEditor")
@MainActor
public func SUITextEditor(_ stateRef: UnsafeMutableRawPointer) -> UnsafeMutableRawPointer {
    let state = Unmanaged<BridgedStringState>.fromOpaque(stateRef).takeUnretainedValue()
    let view = AnyView(BridgedTextEditor(state: state))
    return Unmanaged.passRetained(Box(view)).toOpaque()
}

@MainActor
struct BridgedTextEditor: View {
    var state: BridgedStringState

    var body: some View {
        TextEditor(text: Binding(
            get: { state.value },
