@_cdecl("SUISlider")
@MainActor
public func SUISlider(_ labelPtr: UnsafePointer<CChar>, _ stateRef: UnsafeMutableRawPointer, _ min: Double, _ max: Double, _ callbackID: UInt) -> UnsafeMutableRawPointer {
    let label = String(cString: labelPtr)
    let state = Unmanaged<BridgedIntState>.fromOpaque(stateRef).takeUnretainedValue()
    let view = AnyView(BridgedSlider(label: label, state: state, minValue: min, maxValue: max, callbackID: callbackID))
    return Unmanaged.passRetained(Box(view)).toOpaque()
}

@MainActor
struct BridgedSlider: View {
    let label: String
    var state: BridgedIntState
    let minValue: Double
    let maxValue: Double
    let callbackID: UInt

    var body: some View {
        Slider(value: Binding(
            get: { Double(state.value) },
            set: { state.value = Int($0) }
        ), in: minValue...maxValue) {
            Text(label)
        } onEditingChanged: { editing in
            if !editing {
                _SUIButtonCallback?(callbackID)
            }
        }
    }
}

@_cdecl("SUIPickerSegmented")
@MainActor
public func SUIPickerSegmented(_ labelPtr: UnsafePointer<CChar>, _ stateRef: UnsafeMutableRawPointer, _ optionsRef: UnsafeMutableRawPointer, _ callbackID: UInt) -> UnsafeMutableRawPointer {
    let label = String(cString: labelPtr)
    let state = Unmanaged<BridgedIntState>.fromOpaque(stateRef).takeUnretainedValue()
    let options = Unmanaged<Box<AnyView>>.fromOpaque(optionsRef).takeUnretainedValue().value
    let view = AnyView(BridgedPicker(label: label, state: state, options: options, callbackID: callbackID))
    return Unmanaged.passRetained(Box(view)).toOpaque()
}

@MainActor
struct BridgedPicker: View {
    let label: String
    var state: BridgedIntState
    let options: AnyView
    let callbackID: UInt

    var body: some View {
        Picker(label, selection: Binding(
            get: { state.value },
            set: { newValue in
                state.value = newValue
                _SUIButtonCallback?(callbackID)
            }
        )) {
            options
        }
        .pickerStyle(.segmented)
    }
}

@_cdecl("SUIStepperInt")
@MainActor
public func SUIStepperInt(_ labelPtr: UnsafePointer<CChar>, _ stateRef: UnsafeMutableRawPointer, _ min: Int32, _ max: Int32, _ callbackID: UInt) -> UnsafeMutableRawPointer {
    let label = String(cString: labelPtr)
    let state = Unmanaged<BridgedIntState>.fromOpaque(stateRef).takeUnretainedValue()
    let view = AnyView(BridgedStepper(label: label, state: state, minValue: Int(min), maxValue: Int(max), callbackID: callbackID))
    return Unmanaged.passRetained(Box(view)).toOpaque()
}

@MainActor
struct BridgedStepper: View {
    let label: String
    var state: BridgedIntState
    let minValue: Int
    let maxValue: Int
    let callbackID: UInt

    var body: some View {
        Stepper(label, value: Binding(
            get: { state.value },
            set: { newValue in
                state.value = newValue
                _SUIButtonCallback?(callbackID)
            }
        ), in: minValue...maxValue)
    }
}

